import{c as e,f as t,l as n,n as r,s as i}from"./index-CfWGz4ZE.js";var a=t(n(),1),o=r();function s({compact:e=!1}){let t=(0,a.useId)();return(0,o.jsxs)(`div`,{className:`brand-logo ${e?`brand-logo--compact`:``}`,role:`img`,"aria-label":`از شعر تا داده`,children:[(0,o.jsxs)(`svg`,{className:`brand-mark`,viewBox:`0 0 128 128`,role:`img`,"aria-hidden":`true`,children:[(0,o.jsx)(`defs`,{children:(0,o.jsxs)(`linearGradient`,{id:t,x1:`0`,y1:`0`,x2:`1`,y2:`1`,children:[(0,o.jsx)(`stop`,{offset:`0`,stopColor:`#0b615c`}),(0,o.jsx)(`stop`,{offset:`1`,stopColor:`#b9862d`})]})}),(0,o.jsx)(`path`,{d:`M64 8 114 37v54L64 120 14 91V37Z`,fill:`url(#${t})`}),(0,o.jsx)(`path`,{d:`M64 28 87 56 64 99 41 56Z`,fill:`#fff8e8`}),(0,o.jsx)(`circle`,{cx:`64`,cy:`60`,r:`8`,fill:`#9f2f38`}),(0,o.jsx)(`path`,{d:`M64 68v23`,stroke:`#9f2f38`,strokeWidth:`6`,strokeLinecap:`round`}),(0,o.jsx)(`circle`,{cx:`36`,cy:`42`,r:`5`,fill:`#f0cf79`}),(0,o.jsx)(`circle`,{cx:`92`,cy:`42`,r:`5`,fill:`#f0cf79`}),(0,o.jsx)(`path`,{d:`M40 44 56 55M88 44 72 55`,stroke:`#f0cf79`,strokeWidth:`3`})]}),!e&&(0,o.jsxs)(`div`,{className:`brand-copy`,children:[(0,o.jsx)(`strong`,{children:`از شعر تا داده`}),(0,o.jsx)(`span`,{children:`اطلس تعاملی شعر فارسی`})]})]})}var c=e,l=(e,t=1)=>`${c(e,{minimumFractionDigits:t,maximumFractionDigits:t})}٪`,u=i,d=e=>c(e,{notation:`compact`,maximumFractionDigits:1}),f=[`#0f766e`,`#b45309`,`#9f2f38`,`#2563eb`,`#7c3aed`,`#c2410c`,`#0e7490`,`#4d7c0f`,`#a21caf`,`#475569`,`#d97706`],p=[{id:`topics`,path:`/research/topics/`,title:`تحول مضامین شعر فارسی در سده‌های سوم تا پانزدهم`,shortTitle:`تحول مضامین`,eyebrow:`پژوهش یکم`,description:`تحلیل تعاملی مضمون‌های محاسباتی در پیکره؛ از حکمت و حماسه تا عشق، طبیعت و تصویرپردازی حسی.`,answer:`ترکیب موضوعی مشاهده‌شده در پیکره در طول سده‌های منتسب تغییر می‌کند؛ اندازهٔ اثر و آزمون جایگشتی در صفحهٔ شواهد از دادهٔ canonical ساخته می‌شوند.`,qualification:`مضمون‌های محاسباتی برچسب‌های تفسیری‌اند و سدهٔ منتسب شاعر تاریخ دقیق سرایش یا علت تاریخی تغییر را ثابت نمی‌کند.`,keywords:[`تحلیل مضمون شعر فارسی`,`مدل موضوعی فارسی`,`تاریخ ادبیات فارسی`,`داده‌کاوی شعر`],anchor:`topics`,color:`#0f766e`},{id:`metaphors`,path:`/research/metaphors/`,title:`تولد، خاموشی و دگرگونی استعاره‌ها در شعر فارسی`,shortTitle:`زندگی استعاره‌ها`,eyebrow:`پژوهش دوم`,description:`ردیابی ده خانواده استعاری مانند آینه، آتش، قفس، راه، باده و گل‌وبلبل و بررسی تغییر همسایگان معنایی آن‌ها در سده‌های مختلف.`,answer:`هیچ‌یک از خانواده‌های استعاری بررسی‌شده کاملاً ناپدید نمی‌شوند؛ الگوی غالب، خاموشی موقت، بازگشت و جابه‌جایی میدان معنایی است. تراکم کلی تصاویر میان دوره‌های تاریخی تفاوت معنادار دارد.`,qualification:`واژه‌های عضو یک خانواده می‌توانند کاربرد حقیقی، نمادین یا استعاری داشته باشند؛ شمارش خانواده به‌تنهایی تفسیر ادبی هر رخداد نیست.`,keywords:[`استعاره در شعر فارسی`,`تحول معنایی واژه‌ها`,`آینه در شعر فارسی`,`شبکه هم‌رخدادی`],anchor:`metaphors`,color:`#b9862d`},{id:`intertextuality`,path:`/research/intertextuality/`,title:`نقشه پیوندهای متنی و شباهت شاعران فارسی`,shortTitle:`پیوندهای متنی`,eyebrow:`پژوهش سوم`,description:`نقشه‌ای جهت‌دار از شباهت عبارت‌های نادر، واژگان و الگوی موضوعی میان شاعران متقدم و متأخر؛ در متن عمومی از نام سادهٔ «پیوند متنی» استفاده می‌شود.`,answer:`شباهت عبارتی، واژگانی و موضوعی با افزایش فاصله زمانی شاعران کاهش می‌یابد؛ اما هر پیوند فقط قرابت محاسباتی است و به‌تنهایی تأثیر تاریخی مستقیم را اثبات نمی‌کند.`,qualification:`پیوند جهت‌دار فقط شباهت محاسباتی با تقدم زمانی را نشان می‌دهد و بدون شواهد تاریخی و نسخه‌شناختی حکم تأثیر نیست.`,keywords:[`بینامتنیت شعر فارسی`,`تأثیر شاعران بر یکدیگر`,`شبکه شاعران فارسی`,`شباهت متنی`],anchor:`intertext`,color:`#9f2f38`},{id:`century-ai`,path:`/research/century-ai/`,title:`آیا هوش مصنوعی می‌تواند سده یک شعر فارسی را تشخیص دهد؟`,shortTitle:`تشخیص سده با هوش مصنوعی`,eyebrow:`پژوهش چهارم`,description:`راهنمای علمی تاریخ‌گذاری محاسباتی شعر فارسی و توضیح اینکه چرا ارزیابی Leave-One-Poet-Out برای جلوگیری از تشخیص شاعر به‌جای سده ضروری است.`,answer:`هوش مصنوعی می‌تواند نشانه‌های زمانی را در زبان شعر بیابد، اما دقت ظاهراً بالا در تقسیم تصادفی ممکن است حاصل شناخت شاعر یا کتاب باشد. ارزیابی معتبر باید شاعر آزمون را کاملاً از آموزش حذف کند.`,qualification:`برچسب سده به زندگی شاعر نسبت داده شده و مدل تاریخ دقیق سرایش را پیش‌بینی نمی‌کند؛ نشت هویت شاعر می‌تواند دقت را بیش‌برآورد کند.`,keywords:[`تشخیص سده شعر`,`هوش مصنوعی و شعر فارسی`,`تاریخ‌گذاری متن فارسی`,`یادگیری ماشین ادبیات`],anchor:`century-ai`,color:`#315ba8`},{id:`stylometry`,path:`/research/stylometry/`,title:`اثر انگشت سبکی شاعران و کشف شعرهای نامتعارف`,shortTitle:`اثر انگشت سبکی`,eyebrow:`پژوهش پنجم`,description:`سبک‌سنجی محاسباتی شاعران، شناسایی امضای نویسه‌ای و واژگانی و اولویت‌بندی متن‌های دورافتاده برای بازبینی انسانی.`,answer:`مدل نویسه‌ای در آزمون متوازن از خط مبنا بهتر عمل می‌کند؛ مقدارهای دقیق و تعریف نمونه از دادهٔ پژوهش در صفحهٔ شواهد نمایش داده می‌شوند.`,qualification:`نامتعارف آماری حکم انتساب نادرست نیست و می‌تواند از ژانر، طول، ویرایش، آلودگی داده یا مرحلهٔ متفاوت زندگی شاعر ناشی شود.`,keywords:[`سبک‌سنجی شعر فارسی`,`تشخیص شاعر با هوش مصنوعی`,`اثر انگشت نویسنده`,`کشف انتساب مشکوک`],anchor:`stylometry`,color:`#7c3aed`},{id:`forms`,path:`/research/forms/`,title:`مقایسه تکامل غزل، قصیده، رباعی و مثنوی`,shortTitle:`چهار قالب شعر فارسی`,eyebrow:`پژوهش ششم`,description:`مقایسه عمومی و داده‌محور قالب‌های اصلی برچسب‌خورده؛ از طول و قافیه تا معنا، روایت و امکان تشخیص قالب با هوش مصنوعی.`,answer:`قالب‌های بررسی‌شده در طول، ساختار و الگوی معنایی تفاوت دارند؛ اندازهٔ اثر دقیق و دامنهٔ نمونه از artifact پژوهش به صفحهٔ شواهد می‌آید.`,qualification:`برچسب قالب و نمونهٔ موجود همهٔ تنوع تاریخی هر قالب را پوشش نمی‌دهد و تفاوت آماری جایگزین تحلیل بلاغی یا روایی نیست.`,keywords:[`تفاوت غزل و قصیده`,`مقایسه رباعی و مثنوی`,`قالب‌های شعر فارسی`,`تحلیل ساختار شعر`,`هوش مصنوعی و قالب شعر`],anchor:`forms`,color:`#c45d2a`},{id:`geography`,path:`/research/geography/`,title:`جغرافیای تخیل و مهاجرت شعر فارسی`,shortTitle:`جغرافیای تخیل`,eyebrow:`پژوهش هفتم`,description:`نمایی داده‌محور از خاستگاه، کانون فعالیت و مسیرهای تقریبی جابه‌جایی شاعران، همراه با سنجش تفاوت دوره‌ها، منطقه و شبکهٔ پیوندهای متنی.`,answer:`بخشی از شاعران پیکره در تعریف عملیاتی پژوهش جابه‌جا محسوب می‌شوند و نرخ مشاهده‌شده میان دوره‌ها تفاوت دارد؛ عددها و آزمون‌ها مستقیماً از artifact جغرافیا نمایش داده می‌شوند.`,qualification:`مختصات و مسیرها تقریبی‌اند؛ کانون فعالیت لزوماً محل تولد یا همهٔ سفرهای شاعر نیست و مرزهای فرهنگی با مرزهای سیاسی امروز یکی نیست.`,keywords:[`جغرافیای شعر فارسی`,`مهاجرت شاعران فارسی`,`مسیر سفر شاعران`,`کانون‌های شعر فارسی`,`جغرافیای ادبی`],anchor:`geography`,color:`#0e7490`},{id:`lexical-life`,path:`/research/lexical-life/`,title:`نیمه‌عمر واژگان در شعر فارسی`,shortTitle:`نیمه‌عمر واژگان`,eyebrow:`پژوهش هشتم`,description:`ردیابی تولد مشاهده‌شده، اوج، افت، ماندگاری و بازبرجستگی واژه‌های پرتکرار و چندشاعری در سده‌های منتسب.`,answer:`چرخهٔ واژه‌ها بیشتر تغییر شدت و نقش است تا تولد و مرگ مطلق؛ میانه، نمونهٔ مشاهده‌شده و موارد سانسور راست از artifact پژوهش محاسبه و نمایش داده می‌شوند.`,qualification:`نیمه‌عمر افت فراوانی یک صورت واژگانی است، نه مرگ مفهوم؛ ناهمگنی حجم سده‌ها و چندمعنایی می‌تواند مسیر را تغییر دهد.`,keywords:[`نیمه عمر واژگان`,`تحول واژگان شعر فارسی`,`تاریخ واژه در فارسی`,`واژه‌های رو به افول`,`واژه‌های نوظهور`],anchor:`lexical-life`,color:`#4d7c0f`},{id:`attribution`,path:`/research/attribution/`,title:`سنجش انتساب شعر با شواهد زبانی، فکری و تاریخی`,shortTitle:`انتساب و اعتبار شعر`,eyebrow:`پژوهش نهم`,description:`ممیزی پیکره، مقایسهٔ رباعیات خیام، اولویت‌بندی اشعار منتسب حافظ و تحلیل شاعرمتوازن روندهای مفهومی سده‌ها.`,answer:`پیکرهٔ فعلی برای پالایش، کشف هم‌پوشانی مجموعه‌ها و اولویت‌بندی بازبینی مفید است، اما بدون تاریخ و تبار نسخه‌ها نمی‌تواند حکم قطعی اصالت بدهد؛ شمار هشدارها از artifact ممیزی نمایش داده می‌شود.`,qualification:`این خروجی سیگنال بازبینی است، نه حکم اصالت یا جعل؛ داوری انتساب به نسخه، تاریخ شاهد، تحول متن و ارزیابی متخصص نیاز دارد.`,keywords:[`انتساب شعر فارسی`,`اصالت رباعیات خیام`,`اشعار منتسب حافظ`,`نسخه‌شناسی دیجیتال`,`سبک‌سنجی شعر`],anchor:`attribution`,color:`#7c3aed`},{id:`public-questions`,path:`/research/public-questions/`,title:`ده پرسش جذاب از هزار سال شعر فارسی`,shortTitle:`پرسش‌های کنجکاوی`,eyebrow:`پژوهش دهم`,description:`پاسخ داده‌محور و قابل‌فهم به پرسش‌هایی مانند دل یا عقل، شب یا روز، غم یا شادی، من یا ما، رنگ‌ها، پرندگان و جغرافیای نام‌برده‌شده در شعر.`,answer:`در این پیکره برخی تقابل‌های واژگانی مانند دل/عقل، غم/شادی و من/ما توزیع نابرابر دارند؛ نسبت‌های دقیق از دادهٔ canonical هر پرسش نمایش داده می‌شوند.`,qualification:`این نسبت‌ها شمارش فرهنگ‌های واژگانی تعریف‌شده‌اند و ذات فلسفی یا عاطفی شعر فارسی را ثابت نمی‌کنند؛ نفی، طنز و بافت می‌توانند معنا را عوض کنند.`,keywords:[`پرسش‌های جذاب شعر فارسی`,`دل یا عقل در شعر`,`غم و شادی در شعر فارسی`,`رنگ‌ها در شعر فارسی`,`پرندگان شعر فارسی`],anchor:`curiosity`,color:`#9f2f38`}],m=[{title:`خوانندهٔ عمومی`,label:`مسیر سریع و تصویری`,description:`با نتیجه‌های کلیدی و نمودارهای روایی شروع کنید؛ بدون نیاز به دانش آمار یا برنامه‌نویسی.`,href:`/research/public-questions/`,items:[`ده پرسش جذاب`,`پاسخ یک‌جمله‌ای`,`نمودار و محدودیت`]},{title:`پژوهشگر ادبی`,label:`روش، شواهد و محدودیت‌ها`,description:`صفحات پژوهشی مستقل، روش‌شناسی و آزمون‌های آماری را مرور کنید.`,href:`/research/`,items:[`کنترل عدم‌توازن`,`معناداری آماری`,`راهنمای استناد`]},{title:`پژوهشگر علوم انسانی دیجیتال`,label:`مدل، ارزیابی و بازتولید`,description:`از طراحی تحلیل و عدم‌قطعیت تا آزمون‌ها، موازنهٔ شاعر و رابطهٔ محاسبه با خوانش نزدیک را بررسی کنید.`,href:`/methodology/`,items:[`طراحی تحلیل`,`عدم‌قطعیت`,`بازتولید`]},{title:`کاربر داده`,label:`داده باز و ماشین‌خوان`,description:`خروجی‌های JSON و CSV، واژه‌نامه متغیرها و مستندات بازتولید را دریافت کنید.`,href:`/data/`,items:[`API ایستا`,`CSV نمودارها`,`متادیتای Dataset`]}],h=[{question:`پوشش این پیکره چه معنایی دارد؟`,answer:`شمار متن، بیت، واژه، شاعر و کتاب از artifact انتشار در صفحهٔ اصلی و داده نمایش داده می‌شود. حضور در پیکره نامتوازن است و معادل اهمیت، محبوبیت یا نفوذ ادبی نیست.`},{question:`آیا نمودارها رتبه ادبی شاعران را نشان می‌دهند؟`,answer:`خیر. اندازه خانه‌ها، تعداد متن‌ها یا مرکزیت شبکه فقط ویژگی پیکره و روش محاسباتی را نشان می‌دهد و نباید به ارزش یا اهمیت ادبی تعبیر شود.`},{question:`آیا پیوند متنی، تأثیر مستقیم را ثابت می‌کند؟`,answer:`خیر. یال‌ها قرابت محاسباتی جهت‌دارند؛ یعنی شباهت عبارتی، واژگانی یا موضوعی میان شاعر متأخر و شاعر پیشین دیده شده است. اثبات تأثیر تاریخی به شواهد نسخه‌شناختی و تاریخ ادبی نیاز دارد.`},{question:`آیا شعر نامتعارف حتماً انتساب نادرست دارد؟`,answer:`خیر. کوتاهی یا بلندی متن، تفاوت ژانر، نشانه‌گذاری، آلودگی داده و مرحله متفاوت زندگی شاعر می‌تواند متن را از مرکز سبک او دور کند. خروجی مدل فقط فهرست اولویت بازبینی است.`},{question:`چگونه می‌توان به نتایج استناد کرد؟`,answer:`در هر صفحه پژوهشی یک بلوک استناد آماده، تاریخ به‌روزرسانی و پیوند پایدار وجود دارد. فایل CITATION.cff نیز برای GitHub و ابزارهای مدیریت استناد در پروژه قرار گرفته است.`},{question:`آیا داده‌ها و خروجی نمودارها قابل دانلود هستند؟`,answer:`بله. صفحه داده، خروجی‌های JSON و CSV نمودارها، فهرست شاعران، روند موضوع‌ها، نرخ استعاره‌ها، لبه‌های شبکه، جدول‌های جغرافیا و چرخه عمر واژگان را به‌صورت ماشین‌خوان ارائه می‌کند.`},{question:`آیا نتیجه «غم بیشتر از شادی است» یعنی شعر فارسی ذاتاً غمگین است؟`,answer:`خیر. این نتیجه فقط چگالی یک فرهنگ واژگانی شفاف را مقایسه می‌کند. طنز، نفی، معنای عرفانی و بافت هر بیت می‌تواند جهت عاطفی واژه را تغییر دهد.`},{question:`چرا بعضی واژه‌های جذاب مثل «باز» یا «چین» از رتبه‌بندی حذف شده‌اند؟`,answer:`چون بدون تحلیل بافت بسیار مبهم‌اند: «باز» اغلب یعنی دوباره و «چین» می‌تواند کشور یا چین‌وچروک باشد. حذف آن‌ها از نتیجه‌های چشمگیر اما گمراه‌کننده جلوگیری می‌کند.`},{question:`آیا مسیرهای جابه‌جایی شاعران، سفرنامه دقیق تاریخی‌اند؟`,answer:`خیر. مسیرها و مختصات برای تحلیل کلان تقریبی‌اند. کانون فعالیت نیز لزوماً محل تولد یا درگذشت شاعر نیست و منطقه‌های فرهنگی‌ـ‌تاریخی با مرزهای سیاسی امروز یکسان نیستند.`},{question:`نیمه‌عمر یک واژه یعنی آن واژه مرده است؟`,answer:`خیر. نیمه‌عمر در این پژوهش زمان پس از اوج تا رسیدن فراوانی هموارشده به نصف اوج است. واژه ممکن است پس از آن همچنان فعال باشد یا دوباره برجسته شود؛ واژه نیز با مفهوم یکی نیست.`}],g=[[`اثر انگشت سبکی`,`مجموعه الگوهای ریز و نسبتاً پایدار در انتخاب نویسه، واژه، طول متن و ساختار که می‌تواند میان نویسندگان تفاوت ایجاد کند.`],[`پیوند متنی (بینامتنیت)`,`رابطهٔ یک متن با متن‌های دیگر از راه نقل، بازنویسی، تضمین، تداعی، تصویر مشترک یا شباهت ساختاری. «بینامتنیت» نام دانشگاهی این مفهوم است.`],[`شباهت کسینوسی`,`معیاری میان صفر و یک برای سنجش نزدیکی دو بردار واژگانی یا سبکی؛ هرچه بزرگ‌تر باشد، الگوها نزدیک‌ترند.`],[`مدل موضوعی`,`روش آماری برای کشف گروه‌هایی از واژه‌ها که در متن‌ها با هم ظاهر می‌شوند و می‌توان آن‌ها را به‌صورت مضمون تفسیر کرد.`],[`آزمون جایگشتی`,`روشی برای سنجش معناداری که برچسب‌ها را بارها تصادفی جابه‌جا می‌کند و نتیجه واقعی را با حالت‌های تصادفی مقایسه می‌کند.`],[`اندازه اثر`,`مقدار عملی تفاوت یا رابطه؛ مکمل p-value که نشان می‌دهد یک نتیجه علاوه بر معناداری آماری، تا چه اندازه بزرگ است.`],[`رانش معنایی`,`تغییر واژه‌ها و مفاهیمی که در پیرامون یک واژه مرکزی ظاهر می‌شوند و از دگرگونی کاربرد یا معنای آن خبر می‌دهند.`],[`NPMI`,`معیاری برای سنجش قدرت هم‌رخدادی دو واژه یا دو خانواده تصویری، با کنترل فراوانی عمومی آن‌ها.`],[`Leave-One-Poet-Out`,`طرح ارزیابی که در هر مرحله تمام آثار یک شاعر را برای آزمون کنار می‌گذارد تا مدل نتواند همان شاعر را از داده آموزش حفظ کند.`],[`نامتعارف آماری`,`متنی که بر اساس ویژگی‌های انتخاب‌شده از الگوی معمول آثار همان شاعر فاصله دارد؛ این برچسب داوری ادبی یا حکم انتساب نیست.`],[`کانون فعالیت`,`شهری که برای فعالیت اصلی ادبی یا تاریخی شاعر در داده جغرافیایی ثبت شده است؛ این شهر لزوماً محل تولد یا درگذشت نیست.`],[`نیمه‌عمر واژه`,`زمان پس از اوج تا رسیدن فراوانی هموارشده واژه به نصف مقدار اوج؛ شاخص سرعت افت است، نه زمان مرگ قطعی واژه.`],[`سانسور راست`,`حالتی که رویداد مورد سنجش تا پایان بازه مشاهده رخ نداده است؛ برای نمونه واژه‌ای که تا سده پانزدهم هنوز به نصف اوج نرسیده است.`],[`نرخ شاعرمتوازن`,`ابتدا نرخ یک نشانه برای هر شاعر جدا محاسبه می‌شود و سپس شاعران با وزن برابر در سده میانگین می‌شوند تا دیوان‌های بسیار بزرگ نتیجه را تصاحب نکنند.`],[`پنجره واژگانی`,`چند واژه پیش و پس از یک واژه مرکزی که برای دیدن زمینه نزدیک آن بررسی می‌شوند؛ مثلاً هشت واژه در دو سوی «شب».`]];export{f as a,c,p as i,l,h as n,d as o,g as r,u as s,m as t,s as u};